import * as dntShim from "../../_dnt.shims.js";
import { isJsonMode } from "./json-output.js";
import { isNotFoundError, lstat, realPath } from "../../src/fs/index.js";
import { join, relative } from "../../src/platform/compat/path/index.js";
const PROJECT_LINK_VERSION = 1;
const PROJECT_LINK_DIRECTORY = ".veryfront";
const PROJECT_LINK_FILENAME = "project.json";
export const PROJECT_LINK_RELATIVE_PATH = `${PROJECT_LINK_DIRECTORY}/${PROJECT_LINK_FILENAME}`;
function projectLinkPath(projectDir) {
    return join(projectDir, PROJECT_LINK_DIRECTORY, PROJECT_LINK_FILENAME);
}
function projectLinkPathError() {
    return new Error(`Veryfront cannot use ${PROJECT_LINK_RELATIVE_PATH} through a symbolic link. Remove the link and run the command again.`);
}
function invalidProjectLinkError() {
    return new Error(`Veryfront could not read ${PROJECT_LINK_RELATIVE_PATH}; remove it and relink this project with veryfront push.`);
}
async function lstatIfPresent(path) {
    try {
        return await lstat(path);
    }
    catch (error) {
        if (isNotFoundError(error))
            return null;
        throw error;
    }
}
async function inspectProjectLinkPath(projectDir) {
    const directory = join(projectDir, PROJECT_LINK_DIRECTORY);
    const directoryInfo = await lstatIfPresent(directory);
    if (!directoryInfo)
        return { directoryExists: false, linkExists: false };
    if (directoryInfo.isSymlink)
        throw projectLinkPathError();
    if (!directoryInfo.isDirectory) {
        throw new Error(`${PROJECT_LINK_DIRECTORY} must be a directory inside the project.`);
    }
    const [canonicalProject, canonicalDirectory] = await Promise.all([
        realPath(projectDir),
        realPath(directory),
    ]);
    if (relative(canonicalProject, canonicalDirectory) !== PROJECT_LINK_DIRECTORY) {
        throw projectLinkPathError();
    }
    const linkInfo = await lstatIfPresent(projectLinkPath(projectDir));
    if (!linkInfo)
        return { directoryExists: true, linkExists: false };
    if (linkInfo.isSymlink)
        throw projectLinkPathError();
    if (!linkInfo.isFile) {
        throw new Error(`${PROJECT_LINK_RELATIVE_PATH} must be a file.`);
    }
    return { directoryExists: true, linkExists: true };
}
function normalizeControlPlane(controlPlane) {
    const url = new URL(controlPlane);
    if (url.protocol !== "http:" && url.protocol !== "https:") {
        throw new TypeError("Veryfront control-plane URLs must use HTTP or HTTPS.");
    }
    const pathname = url.pathname.replace(/(?<!\/)\/+$/, "");
    return `${url.origin}${pathname}`;
}
function controlPlanesMatch(left, right) {
    try {
        return normalizeControlPlane(left) === normalizeControlPlane(right);
    }
    catch {
        return false;
    }
}
function isProjectLink(value) {
    if (!value || typeof value !== "object")
        return false;
    const link = value;
    return link.version === PROJECT_LINK_VERSION &&
        isNonEmptyTrimmedString(link.controlPlane) &&
        isControlPlaneUrl(link.controlPlane) &&
        isNonEmptyTrimmedString(link.projectId) &&
        isNonEmptyTrimmedString(link.projectSlug) &&
        (link.previousProjectSlugs === undefined ||
            (Array.isArray(link.previousProjectSlugs) &&
                link.previousProjectSlugs.every(isNonEmptyTrimmedString)));
}
function isNonEmptyTrimmedString(value) {
    return typeof value === "string" && value.length > 0 && value === value.trim();
}
function isControlPlaneUrl(value) {
    try {
        normalizeControlPlane(value);
        return true;
    }
    catch {
        return false;
    }
}
export async function readProjectLink(projectDir) {
    const inspected = await inspectProjectLinkPath(projectDir);
    if (!inspected.linkExists)
        return null;
    try {
        const value = JSON.parse(await dntShim.Deno.readTextFile(projectLinkPath(projectDir)));
        if (isProjectLink(value))
            return value;
    }
    catch {
        throw invalidProjectLinkError();
    }
    throw invalidProjectLinkError();
}
export async function readProjectLinkForControlPlane(projectDir, resolvedApiUrl) {
    const link = await readProjectLink(projectDir);
    if (!link)
        return null;
    if (controlPlanesMatch(link.controlPlane, resolvedApiUrl))
        return link;
    throw new Error(`Veryfront project link ${PROJECT_LINK_RELATIVE_PATH} targets control plane "${link.controlPlane}", but the resolved API URL is "${resolvedApiUrl}". Relink this project or select a matching API URL.`);
}
export async function writeProjectLink(projectDir, link) {
    const directory = join(projectDir, PROJECT_LINK_DIRECTORY);
    const value = {
        version: PROJECT_LINK_VERSION,
        ...link,
        controlPlane: normalizeControlPlane(link.controlPlane),
    };
    const before = await inspectProjectLinkPath(projectDir);
    if (!before.directoryExists)
        await dntShim.Deno.mkdir(directory, { recursive: true });
    await inspectProjectLinkPath(projectDir);
    const path = projectLinkPath(projectDir);
    const temporaryPath = join(directory, `.${PROJECT_LINK_FILENAME}.${dntShim.crypto.randomUUID()}.tmp`);
    try {
        await dntShim.Deno.writeTextFile(temporaryPath, `${JSON.stringify(value, null, 2)}\n`);
        await dntShim.Deno.rename(temporaryPath, path);
    }
    catch (error) {
        try {
            await dntShim.Deno.remove(temporaryPath);
        }
        catch (removeError) {
            if (!isNotFoundError(removeError))
                throw removeError;
        }
        throw error;
    }
    return value;
}
export async function clearProjectLink(projectDir) {
    const inspected = await inspectProjectLinkPath(projectDir);
    if (inspected.linkExists)
        await dntShim.Deno.remove(projectLinkPath(projectDir));
}
/** Track project identity and API origin so collaborators can reuse the association after clone. */
export async function saveSharedProjectAssociation(projectDir, projectSlug, apiUrl, options) {
    const path = join(projectDir, "veryfront.json");
    let existing = {};
    let existingMode;
    try {
        const info = await dntShim.Deno.lstat(path);
        existingMode = info.mode === null ? undefined : info.mode & 0o777;
        if (info.isSymlink || !info.isFile) {
            throw new Error("veryfront.json must be a regular file to save the project association.");
        }
        existing = JSON.parse(await dntShim.Deno.readTextFile(path));
        if (!existing || typeof existing !== "object" || Array.isArray(existing)) {
            throw new Error("veryfront.json must contain a JSON object.");
        }
    }
    catch (error) {
        if (!(error instanceof dntShim.Deno.errors.NotFound))
            throw error;
    }
    if (options?.createNew) {
        await dntShim.Deno.writeTextFile(path, `${JSON.stringify({ projectSlug, ...(apiUrl ? { apiUrl } : {}) }, null, 2)}\n`, { createNew: true });
        return;
    }
    if (!isJsonMode() && typeof existing.apiToken === "string" && existing.apiToken.length > 0) {
        console.warn("veryfront.json contains a legacy apiToken. Run veryfront login, then remove apiToken before committing this shared project association.");
    }
    if (existing.projectSlug === projectSlug && (apiUrl === undefined || existing.apiUrl === apiUrl)) {
        return;
    }
    const temporary = join(projectDir, `.veryfront-association-${dntShim.crypto.randomUUID()}.tmp`);
    try {
        await dntShim.Deno.writeTextFile(temporary, `${JSON.stringify({ ...existing, projectSlug, ...(apiUrl ? { apiUrl } : {}) }, null, 2)}\n`, { createNew: true, mode: existingMode ?? 0o600 });
        if (existingMode !== undefined)
            await dntShim.Deno.chmod(temporary, existingMode);
        await dntShim.Deno.rename(temporary, path);
    }
    catch (error) {
        try {
            await dntShim.Deno.remove(temporary);
        }
        catch (cleanupError) {
            if (!isNotFoundError(cleanupError)) {
                throw new AggregateError([error, cleanupError], "Could not save the project association or remove its temporary file.", { cause: error });
            }
        }
        throw error;
    }
}
